const D = { energy:.6, scale:1, density:.5, speed:1, hue:32, x:.5, y:.56, haze:.55, anno:.55, style:'gaslight', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const T2 = Math.PI*2;
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const lp = (a,b,s) => a+(b-a)*s;
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const AL = cl(P.alpha,20,100)/100;
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const anno = cl(P.anno,0,1);
const NRG = cl(P.energy,0,1);
const HZ = cl(P.haze,0,1);

function pal(){
  if (sty==='engraving') return { g:[38,16,74], fog:[38,10,86], iron:[34,14,54], dark:[28,32,22], line:[28,38,11], hatch:[30,28,28], hot:[38,44,96], win:[44,12,99], dust:[36,14,44], add:false };
  if (sty==='cyanotype') return { g:[213,74,15], fog:[208,54,34], iron:[210,56,30], dark:[214,72,10], line:[200,6,99], hatch:[204,46,56], hot:[192,26,96], win:[196,14,100], dust:[198,26,86], add:false };
  if (sty==='ghost')     return { g:[234,62,7], fog:[H,54,26], iron:[H,58,22], dark:[H,66,10], line:[H,26,98], hatch:[H,44,50], hot:[H+18,66,100], win:[H,20,100], dust:[H,30,88], add:true };
  if (sty==='schematic') return { g:[198,40,8], fog:[192,44,18], iron:[194,44,15], dark:[198,48,6], line:[178,64,92], hatch:[186,42,42], hot:[52,64,92], win:[178,40,88], dust:[178,30,80], add:false };
  return { g:[H,40,15], fog:[H,32,30], iron:[H,24,36], dark:[H,50,10], line:[H,12,84], hatch:[H,28,46], hot:[H+6,74,98], win:[H+8,28,100], dust:[H,24,80], add:false };
}
const C = pal();
const hw = q => ((q%360)+360)%360;
const sc = (c,a) => { stroke(hw(c[0]), c[1], c[2], a*AL); };
const fc = (c,a) => { fill(hw(c[0]), c[1], c[2], a*AL); };
const schem = (sty==='schematic');

// ---- clocks -----------------------------------------------------------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const wob = 1 + .19*Math.sin(K.t*.127) + .12*Math.sin(K.t*.313+1.4) + .06*Math.sin(K.t*.749+2.7);
const shRate = P.speed*(.55 + 1.5*NRG)*wob*(.55+.75*K.intensity);        // rad/s of the line shaft
S.sh = (S.sh||0) + dt*shRate;                                            // main shaft angle, monotonic
const pan = .9*Math.sin(K.t*.047) + .48*Math.sin(K.t*.113+1.7) + .27*Math.sin(K.t*.191+.4);
const bob = .7*Math.sin(K.t*.061+2.1) + .4*Math.sin(K.t*.149+.9);
S.bs = (S.bs||0)*.84 + (A.bass||0)*.16;
const glow = (.42+.58*NRG)*(.55+.5*K.intensity) + S.bs*.3;

// ---- hall geometry ----------------------------------------------------------
const SCA = cl(P.scale,.5,2.0);
const ey = cl(P.y,.30,.80)*height;                 // eye level / horizon
const FH = height*.30*SCA;                         // floor distance below the eye, nearest plane
const CH = height*.46*SCA;                         // ceiling height above the eye, nearest plane
const NP = 4;
const PANX = u*.055*NRG;

// ---- machines ---------------------------------------------------------------
const NM = Math.round(2 + cl(P.density,0,1)*2.4);
const mkey = sd+'|'+NM;
if (S.mk !== mkey){
  S.mk = mkey; S.pl = [];
  for (let p=0;p<NP;p++){
    const ms = [];
    const n = NM + p;
    for (let i=0;i<n;i++){
      ms.push({ fx: (i + .5)/n + (fr(p*13.7+i*3.1)-.5)*.30/n,
                R: .72 + fr(p*7.3+i*5.9)*.42,
                rate: .55 + fr(p*11.1+i*2.7)*1.05,      // incommensurate per machine
                dir: fr(p*3.3+i*9.7) < .5 ? -1 : 1,
                ph: fr(p*17.9+i*4.3)*T2,
                col: fr(p*5.5+i*7.7) < .45 });
    }
    S.pl.push(ms);
  }
}
const planes = S.pl || [];

// ---- cached hall texture ----------------------------------------------------
const gkey = sd+'|'+sty+'|'+width+'x'+height;
if (!S.gr || S.gkey !== gkey){
  if (S.gr && S.gr.remove) S.gr.remove();
  const gw=180, gh=Math.max(60, Math.round(180*height/Math.max(1,width)));
  const g = createGraphics(gw,gh); g.pixelDensity(1); g.loadPixels();
  for (let y=0;y<gh;y++) for (let x=0;x<gw;x++){
    const v = cl(255*(.42 + .34*fr(Math.floor(x/7)*13.71+Math.floor(y/7)*7.33+3.1) + .16*fr(Math.floor(x/3)*3.17+Math.floor(y/3)*11.9+8.7) + .08*fr(x*1.13+y*3.31+1.7)),0,255);
    const j=(y*gw+x)*4; g.pixels[j]=v; g.pixels[j+1]=v; g.pixels[j+2]=v; g.pixels[j+3]=255;
  }
  g.updatePixels(); S.gr = g; S.gkey = gkey;
}

// ---- ground: a vertical tonal wash, dark at the floor, lit at the clerestory -
noStroke();
for (let i=0;i<26;i++){
  const t = i/25;
  const b2 = lp(C.g[2]*.72, C.g[2]*2.9, Math.pow(1-Math.abs(t - .18)*1.15, 2));
  fill(hw(C.g[0]), C.g[1]*lp(1.1,.72,t), cl(b2,2,60), 100);
  rect(0, height*t*1.02, width, height/25+2);
}
push(); blendMode(MULTIPLY); tint(0,0,100, sty==='engraving'?30:24); image(S.gr,0,0,width,height); pop();
blendMode(BLEND); noTint();

// ---- helpers ----------------------------------------------------------------
function beltTangents(x1,y1,r1,x2,y2,r2){
  const dx=x2-x1, dy=y2-y1, Dd=Math.hypot(dx,dy);
  if (Dd < Math.abs(r1-r2)+1e-3) return null;
  const al = Math.atan2(dy,dx), be = Math.acos(cl((r1-r2)/Dd,-1,1));
  return [[x1+Math.cos(al+be)*r1, y1+Math.sin(al+be)*r1, x2+Math.cos(al+be)*r2, y2+Math.sin(al+be)*r2],
          [x1+Math.cos(al-be)*r1, y1+Math.sin(al-be)*r1, x2+Math.cos(al-be)*r2, y2+Math.sin(al-be)*r2]];
}
function flywheel(cx,cy,r,ang,dim,lit){
  const spokes = 6;
  if (schem){ noFill(); sc(C.line, 60*dim); strokeWeight(Math.max(.5,u*.0010)); ellipse(cx,cy,r*2,r*2);
    for (let i=0;i<spokes;i++){ const a=ang+i*T2/spokes; line(cx,cy, cx+Math.cos(a)*r, cy+Math.sin(a)*r); } return; }
  noStroke(); fc(C.iron, (C.add?18:92)*dim); ellipse(cx,cy,r*2,r*2);
  noStroke(); fc(C.dark, (C.add?12:92)*dim); ellipse(cx,cy,r*1.72,r*1.72);
  noFill(); sc(C.line, (56+30*lit)*dim); strokeWeight(Math.max(.6,u*.0016));
  ellipse(cx,cy,r*2,r*2); ellipse(cx,cy,r*1.72,r*1.72);
  sc(C.line, (44+26*lit)*dim); strokeWeight(Math.max(.5,u*.0013));
  for (let i=0;i<spokes;i++){ const a=ang+i*T2/spokes;
    line(cx+Math.cos(a)*r*.16, cy+Math.sin(a)*r*.16, cx+Math.cos(a)*r*.85, cy+Math.sin(a)*r*.85); }
  noStroke(); fc(C.iron, (C.add?22:94)*dim); ellipse(cx,cy,r*.30,r*.30);
  noFill(); sc(C.line, 60*dim); strokeWeight(Math.max(.4,u*.0009)); ellipse(cx,cy,r*.30,r*.30);
  // rim specular: a short bright arc that slides round as the wheel turns
  sc(C.hot, (26+40*lit*glow)*dim); strokeWeight(Math.max(.6,u*.0018));
  arc(cx,cy,r*1.86,r*1.86, ang*.3-.6, ang*.3+.25);
}

// ---- draw the hall, far plane first, veiling between ------------------------
if (C.add) blendMode(ADD);
for (let p=NP-1; p>=0; p--){
  const sp = 1/(1 + p*.62);                      // perspective foreshortening
  const fy = ey + FH*sp;                         // floor line for this plane
  const cy2 = ey - CH*sp;                        // ceiling / shafting line
  const dim = cl(.30 + .70*sp, .26, 1);
  const ox = width*.5 + pan*PANX*sp + (cl(P.x,.2,.8)-.5)*width*.5;
  const spanW = width*(1.02 + p*.22);
  const ms = planes[p] || [];
  const lit = cl(.25 + .75*sp, .2, 1);

  // clerestory: the lit windows the whole hall is lit by
  const wh = CH*sp*.30, ww = spanW/(6+p*2)*.52;
  for (let i=0;i<6+p*2;i++){
    const wx = ox - spanW/2 + (i+.5)*spanW/(6+p*2) + (bob*u*.004*sp);
    noStroke(); fc(C.win, (16 + 30*glow)*dim*(sty==='engraving'?.5:1));
    rect(wx-ww/2, cy2 - wh*1.15, ww, wh);
    noFill(); sc(C.line, 34*dim); strokeWeight(Math.max(.4,u*.0008));
    rect(wx-ww/2, cy2 - wh*1.15, ww, wh);
    sc(C.line, 26*dim); line(wx, cy2-wh*1.15, wx, cy2-wh*.15);
