  // roof trusses
  if (!schem){
    sc(C.line, 40*dim); strokeWeight(Math.max(.4,u*.0009));
    for (let i=0;i<5+p*2;i++){
      const tx = ox - spanW/2 + (i+.5)*spanW/(5+p*2);
      const tw = spanW/(5+p*2)*.5, tht = CH*sp*.13;
      line(tx-tw, cy2-wh*1.2, tx, cy2-wh*1.2-tht); line(tx, cy2-wh*1.2-tht, tx+tw, cy2-wh*1.2);
      line(tx-tw, cy2-wh*1.2, tx+tw, cy2-wh*1.2);
      line(tx, cy2-wh*1.2, tx, cy2-wh*1.2-tht);
      line(tx-tw*.5, cy2-wh*1.2, tx, cy2-wh*1.2-tht*.55);
      line(tx+tw*.5, cy2-wh*1.2, tx, cy2-wh*1.2-tht*.55);
    }
  }
  // the line shaft that drives the whole hall
  const shY = cy2 + CH*sp*.16;
  const shR = u*.011*sp*SCA;
  sc(C.iron, 70*dim); strokeWeight(Math.max(1.2, shR*1.5));
  line(ox-spanW/2, shY, ox+spanW/2, shY);
  sc(C.line, 46*dim); strokeWeight(Math.max(.4,u*.0008));
  line(ox-spanW/2, shY-shR*.7, ox+spanW/2, shY-shR*.7);
  // hangers holding the shaft up to the trusses
  for (let i=0;i<7+p*2;i++){
    const hx = ox - spanW/2 + (i+.5)*spanW/(7+p*2);
    sc(C.line, 40*dim); strokeWeight(Math.max(.4,u*.0009));
    line(hx, cy2-wh*1.2, hx, shY);
    line(hx-shR*1.2, shY-shR, hx+shR*1.2, shY-shR);
  }

  // floor line + engraved floor hatching
  sc(C.line, 34*dim); strokeWeight(Math.max(.5,u*.0011));
  line(0, fy, width, fy);
  if (!schem && anno > .1){
    sc(C.hatch, (10+16*anno)*dim); strokeWeight(Math.max(.4,u*.0007));
    for (let i=0;i<9;i++){ const yy = fy + (i*i)*u*.0035*sp + u*.004;
      if (yy > height) break; line(0, yy, width, yy); }
  }

  // the engines
  for (const m of ms){
    const mx = ox - spanW/2 + m.fx*spanW;
    const R = u*.085*sp*SCA*m.R;
    const wy = fy - R*1.12;
    const ang = S.sh*m.rate*m.dir + m.ph;

    // cast-iron column behind the engine
    if (!schem && m.col){
      const colW = u*.020*sp*SCA, colX = mx + R*1.7;
      noStroke(); fc(C.dark, (C.add?14:92)*dim);
      rect(colX-colW/2, cy2+CH*sp*.2, colW, fy-(cy2+CH*sp*.2));
      noFill(); sc(C.line, 44*dim); strokeWeight(Math.max(.4,u*.0009));
      rect(colX-colW/2, cy2+CH*sp*.2, colW, fy-(cy2+CH*sp*.2));
      rect(colX-colW*.85, fy-colW*.5, colW*1.7, colW*.5);
      sc(C.hatch, 30*dim); strokeWeight(Math.max(.4,u*.0006));
      for (let i=0;i<5;i++) line(colX-colW*.3+i*colW*.14, cy2+CH*sp*.2, colX-colW*.3+i*colW*.14, fy-colW*.5);
    }
    // bedplate
    if (!schem){
      noStroke(); fc(C.dark, (C.add?16:94)*dim);
      rect(mx-R*2.0, fy-R*.20, R*4.0, R*.20);
      noFill(); sc(C.line, 48*dim); strokeWeight(Math.max(.4,u*.0010));
      rect(mx-R*2.0, fy-R*.20, R*4.0, R*.20);
    }
    // belt from the line shaft down to the flywheel (real external tangents)
    const puR = R*.30;
    const tg = beltTangents(mx, shY, puR, mx, wy, R*.86);
    if (tg){
      sc(C.iron, 60*dim); strokeWeight(Math.max(1, u*.0022*sp*SCA));
      for (const t of tg) line(t[0],t[1],t[2],t[3]);
      // the belt is moving: dashes scroll along it at the surface speed
      sc(C.hot, (20+26*glow)*dim); strokeWeight(Math.max(.5,u*.0011*sp*SCA));
      for (const t of tg){
        const bl = Math.hypot(t[2]-t[0], t[3]-t[1]);
        const ux=(t[2]-t[0])/bl, uy=(t[3]-t[1])/bl;
        const off = ((S.sh*m.rate*m.dir*R*.86) % (u*.026)+u*.026) % (u*.026);
        for (let s=off; s<bl; s+=u*.026) line(t[0]+ux*s, t[1]+uy*s, t[0]+ux*Math.min(bl,s+u*.010), t[1]+uy*Math.min(bl,s+u*.010));
      }
      // shaft pulley
      noStroke(); fc(C.iron, (C.add?20:94)*dim); ellipse(mx, shY, puR*2, puR*2);
      noFill(); sc(C.line, 56*dim); strokeWeight(Math.max(.4,u*.0009)); ellipse(mx, shY, puR*2, puR*2);
    }
    flywheel(mx, wy, R, ang, dim, lit);

    // crank-slider: piston x = r cos(t) + sqrt(l^2 - (r sin t)^2). Real geometry.
    const cr = R*.42, rod = R*1.55;
    const cpx = mx + Math.cos(ang)*cr, cpy = wy + Math.sin(ang)*cr;
    const sinT = Math.sin(ang)*cr;
    const chx = mx - (Math.sqrt(Math.max(1e-4, rod*rod - sinT*sinT)) - Math.cos(ang)*cr);
    const chy = wy;
    sc(C.line, (62+24*lit)*dim); strokeWeight(Math.max(.8, u*.0022*sp*SCA));
    line(cpx, cpy, chx, chy);                                  // connecting rod
    noStroke(); fc(C.hot, (44+30*lit)*dim); ellipse(cpx, cpy, R*.16, R*.16);   // crank pin
    if (!schem){
      noStroke(); fc(C.iron, (C.add?22:94)*dim); rect(chx-R*.12, chy-R*.13, R*.24, R*.26);
      noFill(); sc(C.line, 66*dim); strokeWeight(Math.max(.4,u*.0009)); rect(chx-R*.12, chy-R*.13, R*.24, R*.26);
      // piston rod running back into the cylinder
      const cylX = mx - rod - cr*1.25, cylW = R*.62, cylH = R*.42;
      sc(C.line, (58+20*lit)*dim); strokeWeight(Math.max(.6, u*.0016*sp*SCA));
      line(chx-R*.12, chy, cylX+cylW, chy);
      noStroke(); fc(C.dark, (C.add?14:94)*dim); rect(cylX, chy-cylH/2, cylW, cylH);
      noFill(); sc(C.line, 62*dim); strokeWeight(Math.max(.5,u*.0011)); rect(cylX, chy-cylH/2, cylW, cylH);
      sc(C.line, 40*dim); strokeWeight(Math.max(.4,u*.0007));
      line(cylX+cylW*.18, chy-cylH/2, cylX+cylW*.18, chy+cylH/2);
      line(cylX+cylW*.82, chy-cylH/2, cylX+cylW*.82, chy+cylH/2);
      // governor: two flyballs that lift with the shaft speed
      const gvx = mx + R*.9, gvy = fy - R*.85, gl = R*.34;
      const ga = .5 + .5*cl(P.speed*(.4+.6*NRG)*.5, 0, 1);
      sc(C.line, 54*dim); strokeWeight(Math.max(.4,u*.0008));
      line(gvx, gvy, gvx, gvy+gl*1.5);
      for (const s2 of [-1,1]){
        const bxx = gvx + s2*Math.sin(ga)*gl, byy = gvy + Math.cos(ga)*gl;
        line(gvx, gvy, bxx, byy);
        noStroke(); fc(C.iron, 92*dim); ellipse(bxx, byy, R*.11, R*.11);
        noFill(); sc(C.line, 54*dim); strokeWeight(Math.max(.4,u*.0008));
      }
    }
  }

  // haze veil in front of this plane -> atmospheric perspective
  if (p > 0){
    noStroke();
    const va = (5 + 16*HZ) * (1 - sp) * (sty==='engraving' ? .8 : 1);
    for (let i=0;i<5;i++){
      const t=i/4;
      fill(hw(C.fog[0]), C.fog[1]*lp(1,.6,t), C.fog[2]*lp(.75,1.25,t), va*AL*lp(1.25,.6,t));
      rect(0, height*t*.25 + ey - CH*.9, width, height*.30);
    }
    fill(hw(C.fog[0]), C.fog[1], C.fog[2], va*.55*AL);
    rect(0,0,width,height);
  }
}
blendMode(BLEND);

// ---- dust turning in the clerestory light -----------------------------------
{
  const ND = Math.round(30 + cl(P.density,0,1)*50);
  push(); blendMode(sty==='engraving' ? BLEND : ADD); noStroke();
  for (let i=0;i<ND;i++){
    const sp2 = lp(.35, 1, fr(i*3.1+5));
    const dxr = ((fr(i*7.7+2) + K.t*(.006 + .016*fr(i*5.3+9))*sp2*P.speed) % 1.2) - .1;
    const dyr = fr(i*11.3+7) + .05*Math.sin(K.t*(.19+fr(i*2.7)*.4) + i);
    const px2 = dxr*width + pan*PANX*sp2;
    const py2 = (ey - CH*.85) + dyr*(FH+CH)*.92;
    const r = u*.0016*sp2*(1+SCA*.4);
    fc(C.dust, (10 + 30*fr(i*13.1+3)) * (.35+.65*glow) * sp2);
    ellipse(px2, py2, r*2.6, r*2.6);
    fc(C.dust, (26 + 46*fr(i*13.1+3)) * (.35+.65*glow) * sp2);
    ellipse(px2, py2, r, r);
  }
  pop(); blendMode(BLEND);
}

// ---- the clerestory wash, swaying -------------------------------------------
push(); blendMode(SCREEN); noStroke();
const lx = width*(.5 + .30*Math.sin(K.t*.053) + .12*Math.sin(K.t*.137+2.2));
const ly = (ey - CH*.62) + u*.05*Math.sin(K.t*.089+1.1);
for (let i=5;i>=1;i--){ fill(hw(C.hot[0]), C.hot[1]*.5, C.hot[2], (2.0+2.2*glow)*AL); const rw=u*(.26+i*.22); ellipse(lx, ly, rw*2.4, rw*1.5); }
pop(); blendMode(BLEND);

// ---- plate annotation --------------------------------------------------------
if (anno > .35){
  const mgn = u*.026;
  noFill(); sc(C.line, 20+18*anno); strokeWeight(Math.max(.6,u*.0016));
  rect(mgn, mgn, width-mgn*2, height-mgn*2);
  textFont('monospace'); noStroke(); textSize(Math.max(6,u*.0125));
  textAlign(RIGHT, BOTTOM); fc(C.line, 42+30*anno);
  text('ENGINE HALL - '+(NM*NP + (NP*(NP-1)/2))+' SETS ON ONE LINE SHAFT', width-mgn*1.9, height-mgn*1.7);
  textAlign(LEFT, BOTTOM);
  text('LINE SHAFT '+(shRate*60/(Math.PI*2)*13).toFixed(0)+' RPM   SEED '+sd, mgn*1.9, height-mgn*1.7);
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
